const a = Math.abs(P.a), b = Math.abs(P.b);
const step = Math.round(P.step) % 2; // 0 = commutative, 1 = associative-ish reorder
const total = a + b;
// Two tape rows; row 1 = a then b, row 2 = b then a. Same total length.
// animate a sweep marker proving both totals reach the same point.
const sweep = (Math.sin(t * 0.9) * 0.5 + 0.5) * total;
// row 1 (y=4): a (accent) then b (accent2)
v.rect(0.5, 3.6, a, 0.9, { fill: H.colors.accent, stroke: H.colors.ink, width: 1.5 });
v.rect(0.5 + a, 3.6, b, 0.9, { fill: H.colors.accent2, stroke: H.colors.ink, width: 1.5 });
v.text("a + b", 0.5 + total / 2, 4.05, { color: H.colors.bg, size: 13, align: "center", baseline: "middle", weight: 700 });
// row 2 (y=2): b then a  (order swapped)
const firstB = step === 0 ? b : a;
const firstColor = step === 0 ? H.colors.accent2 : H.colors.accent;
const secondLen = step === 0 ? a : b;
const secondColor = step === 0 ? H.colors.accent : H.colors.accent2;
v.rect(0.5, 1.6, firstB, 0.9, { fill: firstColor, stroke: H.colors.ink, width: 1.5 });
v.rect(0.5 + firstB, 1.6, secondLen, 0.9, { fill: secondColor, stroke: H.colors.ink, width: 1.5 });
v.text(step === 0 ? "b + a" : "a + b", 0.5 + total / 2, 2.05, { color: H.colors.bg, size: 13, align: "center", baseline: "middle", weight: 700 });
// the equality marker: same right edge
v.line(0.5 + total, 1.2, 0.5 + total, 4.9, { color: H.colors.good, width: 2, dash: [5, 4] });
